<!doctype html><html lang="fr"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#1f2937;font-size:12px}h1{font-size:22px}.box{border:1px solid #ddd;padding:12px;margin:12px 0}table{width:100%;border-collapse:collapse}th,td{border-bottom:1px solid #ddd;padding:8px;text-align:left}.right{text-align:right}.total{font-size:16px;font-weight:bold}</style></head><body><h1>Bulletin de salaire</h1><p>{{ $statement->reference }} · {{ $statement->period_start->format('d/m/Y') }} – {{ $statement->period_end->format('d/m/Y') }}</p><div class="box"><strong>{{ $statement->staff->name }}</strong><br>{{ $statement->staff->employee_code }} · {{ $statement->staff->employeeType->name }}</div><table><tr><th>Méthode / taux / unités</th><td class="right">{{ $statement->salary_type->value }} · {{ $statement->base_rate }} · {{ $statement->units }}</td></tr><tr><th>Salaire brut</th><td class="right">{{ number_format((float)$statement->gross_salary,2,',',' ') }} {{ $currency }}</td></tr><tr><th>Bonus, exceptionnel et remboursements</th><td class="right">+ {{ number_format((float)$statement->bonuses+(float)$statement->exceptional_payments+(float)$statement->reimbursements,2,',',' ') }} {{ $currency }}</td></tr><tr><th>Déductions et avances</th><td class="right">- {{ number_format((float)$statement->deductions+(float)$statement->advances,2,',',' ') }} {{ $currency }}</td></tr><tr class="total"><th>Net</th><td class="right">{{ number_format((float)$statement->net_salary,2,',',' ') }} {{ $currency }}</td></tr><tr><th>Payé / reste</th><td class="right">{{ number_format((float)$statement->amount_paid,2,',',' ') }} / {{ number_format((float)$statement->remaining_amount,2,',',' ') }} {{ $currency }}</td></tr></table><h2>Paiements</h2><table>@foreach($statement->payments as $payment)<tr><td>{{ $payment->paid_at->format('d/m/Y') }}</td><td>{{ $payment->reference }}</td><td>{{ $payment->payment_method }}</td><td class="right">{{ number_format((float)$payment->amount,2,',',' ') }} {{ $currency }}</td></tr>@endforeach</table></body></html>
